const __pageData = JSON.parse('{"title":"Mohammed bin Salman","description":"","frontmatter":{"title":"Mohammed bin Salman","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["saudi-arabia","house-of-saud","middle-east","mbs","crown-prince"],"sources":["raw/arabian-nights.md","raw/badlands-brief-05f.md","raw/badlands-brief-1ae.md","raw/badlands-brief-174.md","raw/badlands-brief-1c6.md","raw/badlands-brief-509.md","raw/badlands-brief-52f.md","raw/badlands-brief-724.md","raw/badlands-brief-9ea.md","raw/badlands-brief-b56.md","raw/badlands-brief-bf7.md","raw/badlands-brief-bb1.md","raw/badlands-brief-e3f.md","raw/badlands-brief-ea5.md","raw/badlands-brief-f17.md","raw/badlands-news-brief-020.md","raw/badlands-news-brief-079.md","raw/badlands-news-brief-02f.md","raw/badlands-news-brief-0be.md","raw/badlands-news-brief-09e.md","raw/badlands-news-brief-27c.md","raw/badlands-news-brief-2cb.md","raw/badlands-news-brief-311.md","raw/badlands-news-brief-351.md","raw/badlands-news-brief-363.md","raw/badlands-news-brief-36a.md","raw/badlands-news-brief-53f.md","raw/badlands-news-brief-553.md","raw/badlands-news-brief-541.md","raw/badlands-news-brief-582.md","raw/badlands-news-brief-565.md","raw/badlands-news-brief-601.md","raw/badlands-news-brief-69b.md","raw/badlands-news-brief-711.md","raw/badlands-news-brief-677.md","raw/badlands-news-brief-745.md","raw/badlands-news-brief-747.md","raw/badlands-news-brief-7b7.md","raw/badlands-news-brief-7c6.md","raw/badlands-news-brief-824.md","raw/badlands-news-brief-817.md"],"confidence":"medium"},"headers":[],"relativePath":"entities/mohammed-bin-salman.md","filePath":"entities/mohammed-bin-salman.md","lastUpdated":null}');
